-- Clear old milestones
TRUNCATE TABLE public.unlocked_milestones CASCADE;
TRUNCATE TABLE public.milestones CASCADE;

-- Insert 100 milestone definitions

-- Recalculate milestones for all existing profiles
DO $$
DECLARE
    p RECORD;
BEGIN
    FOR p IN SELECT id FROM public.profiles LOOP
        PERFORM public.check_and_unlock_milestones(p.id);
    END LOOP;
END $$;